import random
import string
from typing import List, Tuple

# Generator for Cairo font variations string buffers
# Target: FUZZ_PARAM_STR used by cairo_font_options_set_variations
# The function should return bytes that represent a plausible variations string.
# Examples of valid strings (per OpenType PS-style):
#   "wght=700"
#   "wdth=75"
#   "wght=400,wdth=100,slnt=-10"
#   "GRAD=0.25,opsz=12"
# Axis tags are 4-char tags (A-Z a-z 0-9 space). Cairo commonly sees tags like wght, wdth, slnt, ital, opsz, GRAD, XTRA, XOPQ, YTRA, YOPQ, SOFT, etc.
# Values may be integers or floats, possibly negative. Ranges are font-dependent but typical wght [100..1000], wdth [50..200], slnt [-90..90], opsz [6..72].

_COMMON_AXES = [
    "wght", "wdth", "slnt", "ital", "opsz",
    "GRAD", "XTRA", "XOPQ", "YTRA", "YOPQ", "SOFT", "PWGT", "BLDA",
]

# Additional random 4-char tags to diversify coverage
def rand_tag(rng: random.Random) -> str:
    # 50% choose from common, 50% synthesize a 4-char tag
    if rng.random() < 0.5:
        return rng.choice(_COMMON_AXES)
    # OpenType tags are 4 chars, typically ASCII uppercase; allow mix
    alphabet = string.ascii_letters + string.digits + " "
    # Ensure length 4
    return "".join(rng.choice(alphabet) for _ in range(4))

def rand_value_for_tag(rng: random.Random, tag: str) -> str:
    # Provide reasonable ranges by tag; fallback to generic float/int
    t = tag.lower().strip()
    if t == "wght":
        return str(rng.choice([rng.randrange(100, 1001, 50), rng.uniform(100, 1000)]))
    if t == "wdth":
        # percentage of normal width
        return str(rng.choice([rng.randrange(50, 201, 5), round(rng.uniform(50, 200), 1)]))
    if t == "slnt":
        return str(rng.choice([rng.randrange(-90, 91, 5), round(rng.uniform(-90, 90), 1)]))
    if t == "ital":
        # boolean-ish 0/1 or fractional
        return str(rng.choice([0, 1, round(rng.uniform(0, 1), 2)]))
    if t == "opsz":
        return str(rng.choice([rng.randrange(6, 73), round(rng.uniform(6, 72), 2)]))
    if t in {"grad", "soft", "xtra", "xopq", "ytra", "yopq", "pwgt", "blda"}:
        return str(rng.choice([rng.randrange(-200, 201, 5), round(rng.uniform(-200, 200), 2)]))
    # Generic: mix of ints/floats, some negative
    if rng.random() < 0.5:
        return str(rng.randrange(-1000, 1001))
    return str(round(rng.uniform(-1000, 1000), rng.choice([0, 1, 2, 3])))

def build_variation_pair(rng: random.Random) -> str:
    tag = rand_tag(rng)
    val = rand_value_for_tag(rng, tag)
    # Optionally include whitespace around '=' for parser tolerance
    if rng.random() < 0.3:
        return f"{tag} = {val}"
    return f"{tag}={val}"

def build_variations_string(rng: random.Random) -> str:
    # Choose a style: empty, single pair, multiple pairs, duplicate tags, mixed whitespace
    style = rng.random()
    if style < 0.1:
        # Empty string intentionally valid to clear variations
        return ""
    if style < 0.2:
        # Whitespace-only string
        return " " * rng.randrange(1, 8)
    # 1..N pairs (N capped to keep total < 4096 bytes)
    n = rng.randrange(1, 12)
    pairs = [build_variation_pair(rng) for _ in range(n)]
    # Optionally duplicate a tag to see last-one-wins behavior
    if rng.random() < 0.3 and pairs:
        dup_tag = rng.choice(_COMMON_AXES)
        pairs.append(f"{dup_tag}={rand_value_for_tag(rng, dup_tag)}")
    # Random separators: comma with optional spaces, or commas plus semicolons (commas are canonical)
    sep = "," if rng.random() < 0.8 else ";"
    if rng.random() < 0.6:
        sep = sep + (" " * rng.randrange(0, 2))
    s = sep.join(pairs)
    # Optional surrounding spaces
    if rng.random() < 0.3:
        s = (" " * rng.randrange(0, 3)) + s + (" " * rng.randrange(0, 3))
    # Ensure not exceeding 4096 when encoded
    b = s.encode("utf-8")
    if len(b) > 4096:
        # Trim conservatively at a separator boundary
        cut = 4096
        while cut > 0 and b[cut-1:cut] not in [b",", b";"]:
            cut -= 1
        if cut <= 0:
            b = b[:4096]
        else:
            b = b[:cut]
        s = b.decode("utf-8", errors="ignore")
    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    variations = build_variations_string(rng)
    return variations.encode("utf-8")
